Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "title": {
    "text": "No one dominates: most hosts rent out a single place",
    "subtitle": "Cumulative share of listings, hosts ranked from largest to smallest",
    "anchor": "start",
    "color": "#172541",
    "fontSize": 15,
    "fontWeight": 600,
    "subtitleColor": "#8A7F6E",
    "subtitleFontSize": 11,
    "offset": 10
  },
  "width": 600,
  "height": 190,
  "transform": [
    {
      "filter": "datum[''Host Listings''] > 0"
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "Host Listings",
          "as": "total"
        },
        {
          "op": "count",
          "as": "n"
        }
      ]
    },
    {
      "window": [
        {
          "op": "sum",
          "field": "Host Listings",
          "as": "cum"
        },
        {
          "op": "row_number",
          "as": "rn"
        }
      ],
      "sort": [
        {
          "field": "Host Listings",
          "order": "descending"
        },
        {
          "field": "HOST_ID",
          "order": "ascending"
        }
      ],
      "frame": [
        null,
        0
      ]
    },
    {
      "calculate": "datum.rn / datum.n",
      "as": "host_share"
    },
    {
      "calculate": "datum.cum / datum.total",
      "as": "listing_share"
    }
  ],
  "encoding": {
    "x": {
      "field": "host_share",
      "type": "quantitative",
      "title": "Share of hosts (largest first)",
      "scale": {
        "domain": [
          0,
          1
        ]
      },
      "axis": {
        "format": ".0%",
        "domain": false,
        "ticks": false,
        "gridColor": "#F1EADB",
        "labelColor": "#8A7F6E",
        "titleColor": "#8A7F6E",
        "titleFontWeight": "normal",
        "titleFontSize": 11,
        "labelFontSize": 10,
        "tickCount": 5
      }
    },
    "y": {
      "field": "listing_share",
      "type": "quantitative",
      "title": "Share of listings",
      "scale": {
        "domain": [
          0,
          1
        ]
      },
      "axis": {
        "format": ".0%",
        "domain": false,
        "ticks": false,
        "gridColor": "#F1EADB",
        "labelColor": "#8A7F6E",
        "titleColor": "#8A7F6E",
        "titleFontWeight": "normal",
        "titleFontSize": 11,
        "labelFontSize": 10,
        "tickCount": 5
      }
    }
  },
  "layer": [
    {
      "transform": [
        {
          "filter": "datum.rn == 1"
        }
      ],
      "mark": {
        "type": "rule",
        "strokeDash": [
          4,
          4
        ],
        "color": "#C9BFA9",
        "strokeWidth": 1.5
      },
      "encoding": {
        "x": {
          "datum": 0
        },
        "y": {
          "datum": 0
        },
        "x2": {
          "datum": 1
        },
        "y2": {
          "datum": 1
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.rn == 1"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "dx": 0,
        "dy": 14,
        "fontSize": 10,
        "color": "#8A7F6E",
        "angle": 0,
        "text": "Equal share line"
      },
      "encoding": {
        "x": {
          "datum": 0.97
        },
        "y": {
          "datum": 0.9
        }
      }
    },
    {
      "mark": {
        "type": "area",
        "interpolate": "monotone",
        "color": {
          "x1": 0,
          "y1": 0,
          "x2": 0,
          "y2": 1,
          "gradient": "linear",
          "stops": [
            {
              "offset": 0,
              "color": "rgba(20,97,126,0.35)"
            },
            {
              "offset": 1,
              "color": "rgba(20,97,126,0)"
            }
          ]
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "interpolate": "monotone",
        "strokeWidth": 3,
        "color": "#14617E"
      }
    },
    {
      "transform": [
        {
          "filter": "datum.rn == ceil(datum.n * 0.01) || datum.rn == ceil(datum.n * 0.10)"
        },
        {
          "calculate": "''Top '' + (datum.rn == ceil(datum.n * 0.01) ? ''1%'' : ''10%'') + '' of hosts own '' + format(datum.listing_share, ''.0%'') + '' of listings''",
          "as": "lbl"
        }
      ],
      "layer": [
        {
          "mark": {
            "type": "point",
            "filled": true,
            "size": 90,
            "color": "#F2B632",
            "stroke": "#FFFFFF",
            "strokeWidth": 2
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "dx": 10,
            "dy": 14,
            "fontSize": 11,
            "fontWeight": 600,
            "color": "#B8860B"
          },
          "encoding": {
            "text": {
              "field": "lbl"
            }
          }
        }
      ]
    }
  ],
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI"
  }
}'
